// Step 1: Normalize Telegram Update and Validate Webhook Secret Header
const input = $input.first().json;
const headers = input.headers || {};
const body = input.body || input;

// Support secret token check if present in headers
const webhookSecret = headers['x-telegram-bot-api-secret-token'];

const update = body;
const updateId = update.update_id || (Date.now() % 1000000000);

let message = update.message;
let isEdited = false;
let isCallback = false;
let callbackData = null;

if (update.edited_message) {
  message = update.edited_message;
  isEdited = true;
} else if (update.callback_query) {
  message = update.callback_query.message;
  isCallback = true;
  callbackData = update.callback_query.data;
}

if (!message) {
  return [{
    json: {
      ok: false,
      status: 'ignored',
      error: { category: 'validation', code: 'UNSUPPORTED_UPDATE_TYPE', message_safe: 'No actionable message in update' }
    }
  }];
}

const telegramUserId = update.callback_query ? update.callback_query.from.id : (message.from ? message.from.id : null);
const telegramChatId = message.chat ? message.chat.id : null;
const messageText = message.text || message.caption || callbackData || '';
const messageDate = message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString();

return [{
  json: {
    update_id: updateId,
    telegram_user_id: telegramUserId,
    telegram_chat_id: telegramChatId,
    message_id: message.message_id,
    text: messageText,
    is_edited: isEdited,
    is_callback: isCallback,
    callback_data: callbackData,
    captured_at: messageDate,
    webhook_secret: webhookSecret
  }
}];

const userRows = $input.all();
const norm = $('Normalize Telegram Update').first().json;

if (!userRows || userRows.length === 0 || !userRows[0].json || !userRows[0].json.user_id) {
  return [{
    json: {
      ok: false,
      status: 'error',
      error: {
        category: 'authorization',
        code: 'UNAUTHORIZED_USER_OR_CHAT',
        message_safe: 'Unauthorized Telegram sender or chat'
      }
    }
  }];
}

const user = userRows[0].json;
const correlationId = 'corr_tg_' + Math.random().toString(36).substring(2, 10) + '_' + Date.now();

return [{
  json: {
    contract_version: '1.0',
    correlation_id: correlationId,
    user_id: user.user_id,
    source_channel: 'telegram',
    captured_at: norm.captured_at,
    timezone: user.timezone || 'America/Argentina/Buenos_Aires',
    locale: user.locale || 'es-AR',
    assistant_name: user.assistant_name,
    update_id: norm.update_id,
    message_id: norm.message_id,
    text: norm.text,
    is_edited: norm.is_edited,
    is_callback: norm.is_callback,
    callback_data: norm.callback_data
  }
}];

const auth = $('Validate Auth and Security').first().json;
const ingRaw = $('Register Ingestion RPC').first().json.res;
const ing = typeof ingRaw === 'string' ? JSON.parse(ingRaw) : ingRaw;
const clarRows = $input.all();

if (ing.is_duplicate) {
  return [{
    json: {
      ok: true,
      status: 'duplicate',
      correlation_id: auth.correlation_id,
      ingestion_id: ing.ingestion_id,
      message: 'Duplicate update ignored'
    }
  }];
}

let targetRoute = 'process_text';
let pendingClarification = null;

if (clarRows && clarRows.length > 0 && clarRows[0].json && clarRows[0].json.id) {
  pendingClarification = clarRows[0].json;
}

const textTrimmed = (auth.text || '').trim();

if (textTrimmed.startsWith('/start') || textTrimmed.startsWith('/configuracion') || auth.is_callback) {
  targetRoute = 'onboarding_and_config';
} else if (pendingClarification && !textTrimmed.startsWith('?') && !textTrimmed.toLowerCase().startsWith('no,') && textTrimmed.length < 100) {
  targetRoute = 'resolve_clarification';
}

return [{
  json: {
    ...auth,
    ingestion_id: ing.ingestion_id,
    target_route: targetRoute,
    pending_clarification: pendingClarification
  }
}];
